import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.BfI5QxtK.js";const g=JSON.parse('{"title":"Wayland protocol catalog","description":"","frontmatter":{},"headers":[],"relativePath":"wayland-protocols.md","filePath":"wayland-protocols.md"}'),n={name:"wayland-protocols.md"};function i(d,e,r,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="wayland-protocol-catalog" tabindex="-1">Wayland protocol catalog <a class="header-anchor" href="#wayland-protocol-catalog" aria-label="Permalink to &quot;Wayland protocol catalog&quot;">​</a></h1><p>This page covers the additional protocol globals Gnoblin registers or gates in a Gnoblin session. It does not list every core Wayland or upstream Mutter global. A client must bind the interface advertised by the running compositor; vendored XML alone does not mean a protocol is available.</p><h2 id="configure-availability" tabindex="-1">Configure availability <a class="header-anchor" href="#configure-availability" aria-label="Permalink to &quot;Configure availability&quot;">​</a></h2><p>Gnoblin enables the listed interfaces by default in its own session. Disable one in <code>init.lua</code> with its Lua key:</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gnoblin.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">configure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    protocols </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        wlr_screencopy </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Lua underscores become hyphens in the native setting name. Protocol globals are registered at compositor startup, so <strong>log out and back in</strong> after changing these gates. <code>gnoblinctl config reload</code> cannot add or remove an advertised global. GNOME&#39;s separate login session does not advertise Gnoblin-owned globals.</p><h2 id="available-interfaces" tabindex="-1">Available interfaces <a class="header-anchor" href="#available-interfaces" aria-label="Permalink to &quot;Available interfaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lua key</th><th>Advertised interface</th><th>Max version</th><th>Use it for</th><th>Guide</th></tr></thead><tbody><tr><td><code>wlr_layer_shell</code></td><td><a href="https://github.com/swaywm/wlroots/blob/master/protocol/wlr-layer-shell-unstable-v1.xml" target="_blank" rel="noreferrer"><code>zwlr_layer_shell_v1</code></a></td><td>5</td><td>Bars, docks, launchers, overlays and exclusive zones</td><td><a href="./bring-your-own-shell">Choose a shell</a></td></tr><tr><td><code>wlr_screencopy</code></td><td><code>zwlr_screencopy_manager_v1</code></td><td>3</td><td>Native output capture</td><td><a href="/gnoblin/guides/permissions">Permissions</a></td></tr><tr><td><code>ext_foreign_toplevel_list</code></td><td><code>ext_foreign_toplevel_list_v1</code></td><td>1</td><td>Enumerate toplevel windows</td><td><a href="./shell-integration">Shell integration</a></td></tr><tr><td><code>wlr_foreign_toplevel_management</code></td><td><code>zwlr_foreign_toplevel_manager_v1</code></td><td>3</td><td>Inspect and control windows</td><td><a href="./shell-integration">Shell integration</a></td></tr><tr><td><code>ext_data_control</code></td><td><code>ext_data_control_manager_v1</code></td><td>1</td><td>Clipboard managers</td><td><a href="/gnoblin/guides/session_settings">Session settings</a></td></tr><tr><td><code>ext_idle_notify</code></td><td><code>ext_idle_notifier_v1</code></td><td>2</td><td>Idle notifications</td><td><a href="/gnoblin/guides/session_settings">Session settings</a></td></tr><tr><td><code>ext_session_lock</code></td><td><code>ext_session_lock_manager_v1</code></td><td>1</td><td>Lock the session with an external locker</td><td><a href="./session-lock">Session locking</a></td></tr><tr><td><code>wlr_gamma_control</code></td><td><code>zwlr_gamma_control_manager_v1</code></td><td>1</td><td>Per-output gamma</td><td><a href="/gnoblin/guides/session_settings">Session settings</a></td></tr><tr><td><code>wlr_output_power_management</code></td><td><code>zwlr_output_power_manager_v1</code></td><td>1</td><td>Output power state</td><td><a href="/gnoblin/guides/session_settings">Session settings</a></td></tr><tr><td><code>ext_background_effect_v1</code></td><td><code>ext_background_effect_manager_v1</code></td><td>1</td><td>Client-defined background blur regions</td><td><a href="./background-effects">Background blur</a></td></tr><tr><td><code>xdg_decoration</code></td><td><code>zxdg_decoration_manager_v1</code></td><td>1</td><td>Negotiate client or server titlebars</td><td><a href="/gnoblin/guides/window_frames">Window frames</a></td></tr><tr><td><code>window_frame_renderer</code></td><td><code>gnoblin_window_frame_manager_v1</code></td><td>1</td><td>External frame renderer service</td><td><a href="./frame-renderer-api">Frame renderer API</a></td></tr><tr><td><code>blur_fade</code></td><td><code>gnoblin_blur_fade_manager_v1</code></td><td>1</td><td>Per-item blur fade metadata</td><td><a href="./blur-fades">Blur fades</a></td></tr></tbody></table><p>The <code>Max version</code> column is the version Gnoblin advertises; clients can bind that version or a lower one. The XML shipped under <code>src/protocols/</code> is the wire-level reference for Gnoblin-owned implementations. For standard protocol requests, events and enum values, see the <a href="https://wayland.freedesktop.org/docs/book/" target="_blank" rel="noreferrer">Wayland protocol documentation</a> and the <a href="https://gitlab.freedesktop.org/wayland/wayland-protocols" target="_blank" rel="noreferrer">wayland-protocols source</a>. This catalog explains which interface to use and where its behavior is documented.</p><p>For example, a layer-shell client controls its anchors, keyboard interactivity and exclusive zone. Gnoblin then places the surface and applies any matching <code>type = &quot;layer&quot;</code> <a href="/gnoblin/guides/window_rules">window rules</a>. A panel that animates its own whole surface can disable the compositor&#39;s layer animation for its namespace.</p><p>Screen capture through <code>wlr_screencopy</code> is separate from capture through the desktop portal. The latter follows <a href="/gnoblin/guides/permissions">portal permission policy</a>. Turning off this global is not a blanket screen-sharing policy.</p><h2 id="session-locking" tabindex="-1">Session locking <a class="header-anchor" href="#session-locking" aria-label="Permalink to &quot;Session locking&quot;">​</a></h2><p>Gnoblin advertises the standard <code>ext-session-lock-v1</code> manager in the Gnoblin session. The first locker to acquire it owns the active lock; a second locker receives <code>finished</code>. The compositor covers every output, keeps the session locked if the client exits, and sends <code>locked</code> only after its covered frame has presented.</p><p>Gnoblin deliberately has no built-in lock UI or locker policy. Bingux ships a separate lock client, and unmodified clients such as hyprlock, swaylock, gtklock and waylock can use the same protocol. The regular GNOME session never receives this global and retains GNOME ScreenShield.</p><p>Portal permissions do not change when the session locks. An already authorised monitor stream sees the compositor lock scene instead of desktop content. Remote input is available after <code>locked</code> and lock-scene presentation, and goes only to the active lock surface; it is refused during transitions and failsafe. No lock-specific portal configuration is needed. See <a href="./session-lock">session locking</a>.</p><p><code>zwlr_output_manager_v1</code> remains vendored XML only and is not an advertised Gnoblin global.</p><h2 id="inspect-a-running-session" tabindex="-1">Inspect a running session <a class="header-anchor" href="#inspect-a-running-session" aria-label="Permalink to &quot;Inspect a running session&quot;">​</a></h2><p>Check the running compositor when packaging or debugging a client. A Wayland registry inspector such as <code>wayland-info</code> can show advertised globals; run it inside the Gnoblin session or devkit terminal so it connects to the right <code>WAYLAND_DISPLAY</code>. A source checkout, package manifest or XML file cannot prove that a particular login session has advertised a global.</p>`,18)])])}const u=t(n,[["render",i]]);export{g as __pageData,u as default};
